alter table public.ei_documents add column kind text not null default 'ei';
alter table public.ei_documents add constraint ei_documents_kind_check check (kind in ('ei','briefing'));

drop index if exists ei_documents_client_unique;
create unique index ei_documents_client_kind_unique on public.ei_documents(client_id, kind) where client_id is not null;

drop index if exists ei_documents_one_template;
create unique index ei_documents_one_template_per_kind on public.ei_documents(kind) where is_template;

